        throw ioe;
      }
      if (nsId.isEmpty()) {
        throw ioe;
      }
      Set<FederationNamespaceInfo> nssWithoutFailed = getNameSpaceInfo(nsId, nss);
      return invokeOnNs(method, clazz, ioe, nssWithoutFailed);
    }
  }
```

