51	 */
52	public class DynamicRouterRpcFairnessPolicyController
53	    extends StaticRouterRpcFairnessPolicyController {
54	
55	  private static final Logger LOG =
56	      LoggerFactory.getLogger(DynamicRouterRpcFairnessPolicyController.class);
57	
58	  private static final ScheduledExecutorService SCHEDULED_EXECUTOR = HadoopExecutors
59	      .newSingleThreadScheduledExecutor(new ThreadFactoryBuilder().setDaemon(true)
60	          .setNameFormat("DynamicRouterRpcFairnessPolicyControllerPermitsResizer").build());
61	  private PermitsResizerService permitsResizerService;
62	  private ScheduledFuture<?> refreshTask;
63	  private int handlerCount;
64	  private int minimumHandlerPerNs;
65	
66	  /**
67	   * Initializes using the same logic as {@link StaticRouterRpcFairnessPolicyController}
68	   * and starts a periodic semaphore resizer thread.
69	   *
70	   * @param conf configuration
71	   */
72	  public DynamicRouterRpcFairnessPolicyController(Configuration conf) {
73	    super(conf);
74	    minimumHandlerPerNs = conf.getInt(DFS_ROUTER_FAIR_MINIMUM_HANDLER_COUNT_KEY,
75	        DFS_ROUTER_FAIR_MINIMUM_HANDLER_COUNT_DEFAULT);
76	    handlerCount = conf.getInt(DFS_ROUTER_HANDLER_COUNT_KEY, DFS_ROUTER_HANDLER_COUNT_DEFAULT);
77	    long refreshInterval =
78	        conf.getTimeDuration(DFS_ROUTER_DYNAMIC_FAIRNESS_CONTROLLER_REFRESH_INTERVAL_SECONDS_KEY,
79	            DFS_ROUTER_DYNAMIC_FAIRNESS_CONTROLLER_REFRESH_INTERVAL_SECONDS_DEFAULT,
80	            TimeUnit.SECONDS);
81	    permitsResizerService = new PermitsResizerService();
82	    refreshTask = SCHEDULED_EXECUTOR
83	        .scheduleWithFixedDelay(permitsResizerService, refreshInterval, refreshInterval,
84	            TimeUnit.SECONDS);
85	  }
86	
87	  @VisibleForTesting
88	  public DynamicRouterRpcFairnessPolicyController(Configuration conf, long refreshInterval) {
89	    super(conf);
90	    minimumHandlerPerNs = conf.getInt(DFS_ROUTER_FAIR_MINIMUM_HANDLER_COUNT_KEY,
91	        DFS_ROUTER_FAIR_MINIMUM_HANDLER_COUNT_DEFAULT);
92	    handlerCount = conf.getInt(DFS_ROUTER_HANDLER_COUNT_KEY, DFS_ROUTER_HANDLER_COUNT_DEFAULT);
93	    permitsResizerService = new PermitsResizerService();
94	    refreshTask = SCHEDULED_EXECUTOR
95	        .scheduleWithFixedDelay(permitsResizerService, refreshInterval, refreshInterval,
96	            TimeUnit.SECONDS);
97	  }
98	
99	  @VisibleForTesting
100	  public void refreshPermitsCap() {
101	    permitsResizerService.run();
102	  }
103	
104	  @Override
105	  public void shutdown() {
106	    super.shutdown();
107	    if (refreshTask != null) {
108	      refreshTask.cancel(true);
109	    }
110	    if (SCHEDULED_EXECUTOR != null) {
111	      SCHEDULED_EXECUTOR.shutdown();
112	    }
113	  }
114	
115	  class PermitsResizerService implements Runnable {
116	
117	    @Override
118	    public synchronized void run() {
119	      if ((getRejectedPermitsPerNs() == null) || (getAcceptedPermitsPerNs() == null)) {
120	        return;
121	      }
122	      long totalOps = 0;
123	      Map<String, Long> nsOps = new HashMap<>();
124	      for (Map.Entry<String, AdjustableSemaphore> entry : getPermits().entrySet()) {
125	        long ops = (getRejectedPermitsPerNs().containsKey(entry.getKey()) ?
126	            getRejectedPermitsPerNs().get(entry.getKey()).longValue() :
127	            0) + (getAcceptedPermitsPerNs().containsKey(entry.getKey()) ?
128	            getAcceptedPermitsPerNs().get(entry.getKey()).longValue() :
129	            0);
130	        nsOps.put(entry.getKey(), ops);
131	        totalOps += ops;
132	      }
133	
134	      List<String> underMinimumNss = new ArrayList<>();
135	      List<String> overMinimumNss = new ArrayList<>();
136	      int effectiveOps = 0;
137	
138	      // First iteration: split namespaces into those underused and those that are not.
139	      for (Map.Entry<String, AdjustableSemaphore> entry : getPermits().entrySet()) {
140	        String ns = entry.getKey();
141	        int newPermitCap = (int) Math.ceil((float) nsOps.get(ns) / totalOps * handlerCount);
142	
143	        if (newPermitCap <= minimumHandlerPerNs) {
144	          underMinimumNss.add(ns);
145	        } else {
146	          overMinimumNss.add(ns);
147	          effectiveOps += nsOps.get(ns);
148	        }
149	      }
150	
151	      // Second iteration part 1: assign minimum handlers
152	      for (String ns: underMinimumNss) {
153	        resizeNsHandlerCapacity(ns, minimumHandlerPerNs);
154	      }
155	      // Second iteration part 2: assign handlers to the rest
156	      int leftoverPermits = handlerCount - minimumHandlerPerNs * underMinimumNss.size();
157	      for (String ns: overMinimumNss) {
158	        int newPermitCap = (int) Math.ceil((float) nsOps.get(ns) / effectiveOps * leftoverPermits);
159	        resizeNsHandlerCapacity(ns, newPermitCap);
160	      }
161	    }
162	
163	    private void resizeNsHandlerCapacity(String ns, int newPermitCap) {
164	      AdjustableSemaphore semaphore = getPermits().get(ns);
165	      int oldPermitCap = getPermitSizes().get(ns);
166	      if (newPermitCap <= minimumHandlerPerNs) {
167	        newPermitCap = minimumHandlerPerNs;
168	      }
169	      getPermitSizes().put(ns, newPermitCap);
170	      if (newPermitCap > oldPermitCap) {
171	        semaphore.release(newPermitCap - oldPermitCap);
172	      } else if (newPermitCap < oldPermitCap) {
173	        semaphore.reducePermits(oldPermitCap - newPermitCap);
174	      }
175	      LOG.info("Resized handlers for nsId {} from {} to {}", ns, oldPermitCap, newPermitCap);
176	    }
177	  }
178	}

